# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Triton implementation of aten::smm (sparse COO x dense -> sparse COO).

Reference semantics on the target (torch 2.10 + torch_npu, CPU fallback oracle):
    torch.smm(self, mat2) -> COO (M, N) whose structural pattern is: every row
    of ``self`` that stores at least one entry contributes all ``N`` columns
    (explicit zeros included); rows without stored entries contribute none.
    is_coalesced() is False for a non-empty result and True for an empty one.

Design (coalesced path: 3 kernels + one host scalar read, no atomics and no
data-dependent-address stores):
  1. ``_smm_ranges``  : BS rows per program; each row locates its segment with a
                        vectorized lower_bound over the sorted row-index array.
                        Writes contiguous CSR offsets, a contiguous per-block
                        exclusive presence prefix and the block totals.
  2. ``_smm_bprefix`` : exclusive prefix over the few block totals.
  3. ``_smm_main``    : one program per (row, column tile); skips rows that store
                        no entry, streams the row's entries, accumulates in fp32
                        and writes the COO values plus both index rows.

A non-coalesced input takes a counting-sort fallback
(``_smm_count``/``_smm_scan``/``_smm_permute``) before the same main kernel.
"""

import torch
import triton
import triton.language as tl

# ---------------------------------------------------------------- kernels


@triton.jit
def _smm_ranges(
    row_idx, row_stride, row_ptr, lrank, btotal, nnz, M, nblk, NIT, BS: tl.constexpr
):
    pid = tl.program_id(0)
    r = pid * BS + tl.arange(0, BS)
    rm = r < M

    lo = tl.zeros((BS,), dtype=tl.int32)
    hi = tl.zeros((BS,), dtype=tl.int32) + nnz
    nmax = nnz - 1
    for _ in range(0, NIT):
        active = rm & (lo < hi)
        mid = (lo + hi) >> 1
        # Unmasked probe on a clamped address: inactive lanes' results are
        # discarded by the lo/hi updates, and avoiding the mask keeps the
        # gather out of the scalar predicated path.
        val = tl.load(row_idx + tl.minimum(mid, nmax) * row_stride).to(tl.int32)
        ltm = active & (val < r)
        gtm = active & (val >= r)
        lo = tl.where(ltm, mid + 1, lo)
        hi = tl.where(gtm, mid, hi)

    v0 = tl.load(row_idx + tl.minimum(lo, nmax) * row_stride).to(tl.int32)
    pres = (rm & (lo < nnz) & (v0 == r)).to(tl.int32)

    inc = tl.cumsum(pres, 0)
    tl.store(row_ptr + r, lo, mask=rm)
    tl.store(lrank + r, inc - pres, mask=rm)
    tl.store(btotal + pid, tl.sum(pres, 0))
    if pid == nblk - 1:
        tl.store(row_ptr + M, nnz)


@triton.jit
def _smm_bprefix(btotal, bprefix, rbuf, nblk, NB: tl.constexpr):
    off = tl.arange(0, NB)
    m = off < nblk
    c = tl.load(btotal + off, mask=m, other=0)
    inc = tl.cumsum(c, 0)
    tl.store(bprefix + off, inc - c, mask=m)
    tl.store(rbuf, tl.sum(c, 0))


@triton.jit
def _smm_count(row_idx, row_stride, counts, nnz, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    off = pid * BLOCK + tl.arange(0, BLOCK)
    m = off < nnz
    r = tl.load(row_idx + off * row_stride, mask=m, other=0).to(tl.int32)
    tl.atomic_add(counts + r, 1, mask=m)


@triton.jit
def _smm_scan(counts, row_ptr, cursor, lrank, rbuf, M, BS: tl.constexpr):
    tl.store(row_ptr, 0)
    carry = M * 0
    pcarry = M * 0
    for base_i in range(0, M, BS):
        off = base_i + tl.arange(0, BS)
        m = off < M
        c = tl.load(counts + off, mask=m, other=0).to(tl.int32)
        inc = tl.cumsum(c, 0)
        pos = inc - c + carry
        tl.store(row_ptr + off + 1, pos + c, mask=m)
        tl.store(cursor + off, pos, mask=m)
        pres = (c > 0).to(tl.int32)
        tl.store(lrank + off, tl.cumsum(pres, 0) - pres + pcarry, mask=m)
        carry += tl.sum(c, 0)
        pcarry += tl.sum(pres, 0)
    tl.store(rbuf, pcarry)


@triton.jit
def _smm_permute(
    row_idx,
    row_stride,
    col_ptr,
    col_off,
    cursor,
    sorted_col,
    sorted_val,
    val_ptr,
    val_stride,
    nnz,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    off = pid * BLOCK + tl.arange(0, BLOCK)
    m = off < nnz
    r = tl.load(row_idx + off * row_stride, mask=m, other=0).to(tl.int32)
    c = tl.load(col_ptr + off * row_stride + col_off, mask=m, other=0)
    v = tl.load(val_ptr + off * val_stride, mask=m, other=0.0)
    pos = tl.atomic_add(cursor + r, 1, mask=m)
    tl.store(sorted_col + pos, c.to(tl.int32), mask=m)
    tl.store(sorted_val + pos, v, mask=m)


_MAIN_CONFIGS = [
    triton.Config({}, num_warps=1, num_stages=3),
    triton.Config({}, num_warps=2, num_stages=3),
    triton.Config({}, num_warps=4, num_stages=3),
    triton.Config({}, num_warps=8, num_stages=3),
]


@triton.autotune(configs=_MAIN_CONFIGS, key=["N", "BJ", "BN"])
@triton.jit
def _smm_main(
    col_ptr,
    col_stride,
    col_off,
    val_ptr,
    val_stride,
    row_ptr,
    lrank,
    bprefix,
    b_ptr,
    out_val,
    out_i0,
    out_i1,
    N,
    stride_bk,
    stride_bn,
    LBS,
    BJ: tl.constexpr,
    BN: tl.constexpr,
    EVEN_N: tl.constexpr,
    HAS_BP: tl.constexpr,
):
    r = tl.program_id(0)
    pid_n = tl.program_id(1)

    start = tl.load(row_ptr + r)
    end = tl.load(row_ptr + r + 1)

    if end > start:
        base_pos = tl.load(lrank + r)
        if HAS_BP:
            base_pos += tl.load(bprefix + (r >> LBS))
        n_off = pid_n * BN + tl.arange(0, BN)
        n_off = tl.max_contiguous(tl.multiple_of(n_off, BN), BN)

        acc = tl.zeros((BN,), dtype=tl.float32)
        if EVEN_N:
            for b0 in range(start, end, BJ):
                e = b0 + tl.arange(0, BJ)
                em = e < end
                k = tl.load(col_ptr + e * col_stride + col_off, mask=em, other=0)
                v = tl.load(val_ptr + e * val_stride, mask=em, other=0.0)
                b = tl.load(
                    b_ptr + k[:, None] * stride_bk + n_off[None, :] * stride_bn,
                    mask=em[:, None],
                    other=0.0,
                )
                acc += tl.sum(v[:, None] * b, axis=0)
        else:
            nm = n_off < N
            for b0 in range(start, end, BJ):
                e = b0 + tl.arange(0, BJ)
                em = e < end
                k = tl.load(col_ptr + e * col_stride + col_off, mask=em, other=0)
                v = tl.load(val_ptr + e * val_stride, mask=em, other=0.0)
                b = tl.load(
                    b_ptr + k[:, None] * stride_bk + n_off[None, :] * stride_bn,
                    mask=em[:, None] & nm[None, :],
                    other=0.0,
                )
                acc += tl.sum(v[:, None] * b, axis=0)

        pos = base_pos.to(tl.int64) * N + n_off
        r64 = r.to(tl.int64)
        c64 = n_off.to(tl.int64)
        if EVEN_N:
            tl.store(out_val + pos, acc.to(out_val.dtype.element_ty))
            tl.store(out_i0 + pos, r64)
            tl.store(out_i1 + pos, c64)
        else:
            nm = n_off < N
            tl.store(out_val + pos, acc.to(out_val.dtype.element_ty), mask=nm)
            tl.store(out_i0 + pos, r64, mask=nm)
            tl.store(out_i1 + pos, c64, mask=nm)


# ---------------------------------------------------------------- host


def _empty_out(M, N, dtype, device):
    ind = torch.empty((2, 0), dtype=torch.int64, device=device)
    val = torch.empty((0,), dtype=dtype, device=device)
    return torch.sparse_coo_tensor(ind, val, (M, N), device=device, is_coalesced=True)


def _pow2_le(x, cap):
    p = 1
    while p * 2 <= x and p * 2 <= cap:
        p *= 2
    return p


def _pow2_ge(x):
    p = 1
    while p < x:
        p *= 2
    return p


def smm(self, mat2):
    if not isinstance(self, torch.Tensor) or not isinstance(mat2, torch.Tensor):
        raise TypeError("smm expects two tensors")
    if not self.is_sparse:
        raise RuntimeError("tensor.sspaddmm(...) can only be called on sparse tensors")
    if self.ndim != 2:
        raise RuntimeError(
            "sspaddmm: Argument #2: matrices expected, got %dD tensor" % self.ndim
        )
    if mat2.is_sparse:
        raise RuntimeError(
            "Cannot access data pointer of Tensor that doesn't have storage"
        )
    if mat2.ndim != 2:
        raise RuntimeError(
            "sspaddmm: Argument #3: matrices expected, got %dD tensor" % mat2.ndim
        )
    if self.layout != torch.sparse_coo:
        raise RuntimeError("smm can only be called on sparse COO tensors")

    M, K = self.shape
    K2, N = mat2.shape
    if K != K2:
        raise RuntimeError(
            "sspaddmm: Argument #3: Expected dim 0 size %d, got %d" % (K, K2)
        )
    if self.dtype != mat2.dtype:
        raise RuntimeError(
            "expected scalar type %s but found %s" % (mat2.dtype, self.dtype)
        )
    if mat2.device != self.device:
        raise RuntimeError(
            "Expected all tensors to be on the same device, but got mat2 is on "
            "%s, different from other tensors on %s" % (mat2.device, self.device)
        )

    device = mat2.device
    out_dtype = mat2.dtype

    sorted_input = self.is_coalesced()
    idx = self._indices()
    vals = self._values()
    nnz = vals.numel()

    if nnz == 0 or N == 0 or M == 0:
        return _empty_out(M, N, out_dtype, device)

    s0 = idx.stride(0)
    s1 = idx.stride(1)
    val_stride = vals.stride(0)

    row_ptr = torch.empty(M + 1, dtype=torch.int32, device=device)
    lrank = torch.empty(M, dtype=torch.int32, device=device)
    rbuf = torch.empty(1, dtype=torch.int32, device=device)

    if sorted_input:
        # Target ~20 range programs (one per AI core): the per-lane
        # dependent-load chain of the lower_bound does not vectorize, so wall
        # time tracks lanes-per-program x iterations and only more blocks help.
        BS = _pow2_ge(max(1, (M + 19) // 20))
        if BS > 128:
            BS = 128
        LBS = BS.bit_length() - 1
        nblk = (M + BS - 1) // BS
        btotal = torch.empty(nblk, dtype=torch.int32, device=device)
        nit = max(1, int(nnz).bit_length())
        _smm_ranges[(nblk,)](idx, s1, row_ptr, lrank, btotal, nnz, M, nblk, nit, BS=BS)
        if nblk > 1:
            bprefix = torch.empty(nblk, dtype=torch.int32, device=device)
            _smm_bprefix[(1,)](btotal, bprefix, rbuf, nblk, NB=_pow2_ge(nblk))
            has_bp = True
            R = int(rbuf.item())
        else:
            bprefix = btotal
            has_bp = False
            R = int(btotal[0].item())
        col_ptr = idx
        col_stride = s1
        col_off = s0
        val_ptr = vals
        val_stride_use = val_stride
    else:
        counts = torch.zeros(M, dtype=torch.int32, device=device)
        cursor = torch.empty(M, dtype=torch.int32, device=device)
        _smm_count[(triton.cdiv(nnz, 512),)](idx, s1, counts, nnz, BLOCK=512)
        _smm_scan[(1,)](counts, row_ptr, cursor, lrank, rbuf, M, BS=1024)
        sorted_col = torch.empty(nnz, dtype=torch.int32, device=device)
        sorted_val = torch.empty(nnz, dtype=vals.dtype, device=device)
        _smm_permute[(triton.cdiv(nnz, 1024),)](
            idx,
            s1,
            idx,
            s0,
            cursor,
            sorted_col,
            sorted_val,
            vals,
            val_stride,
            nnz,
            BLOCK=1024,
        )
        col_ptr = sorted_col
        col_stride = 1
        col_off = 0
        val_ptr = sorted_val
        val_stride_use = 1
        bprefix = lrank
        has_bp = False
        LBS = 0
        R = int(rbuf.item())

    RN = R * N
    out_values = torch.empty(RN, dtype=out_dtype, device=device)
    out_indices = torch.empty((2, RN), dtype=torch.int64, device=device)

    # Measured tile blend: for wide outputs (N>=256) BN=256 with BJ capped by the
    # 8192-element UB budget is the best measured point (round 4), while for
    # narrow outputs (N<=128) one gather iteration is better (round 6), so take
    # the smallest BJ that covers an average row in a single pass.
    davg_i = max(1, int(round(nnz / float(M))))
    if N <= 64:
        BN = 64
    elif N <= 128:
        BN = 128
    else:
        BN = 256
    max_bj = max(1, 8192 // BN)
    BJ = _pow2_ge(davg_i)
    if BJ > max_bj:
        BJ = max_bj

    _smm_main[(M, triton.cdiv(N, BN))](
        col_ptr,
        col_stride,
        col_off,
        val_ptr,
        val_stride_use,
        row_ptr,
        lrank,
        bprefix,
        mat2,
        out_values,
        out_indices[0],
        out_indices[1],
        N,
        mat2.stride(0),
        mat2.stride(1),
        LBS,
        BJ=BJ,
        BN=BN,
        EVEN_N=(N % BN == 0),
        HAS_BP=has_bp,
    )

    # torch.smm (the correctness oracle) reports is_coalesced()==False for any
    # non-empty result, so leave the constructor flag unset here; the empty
    # result is flagged coalesced like the reference.
    return torch.sparse_coo_tensor(out_indices, out_values, (M, N), device=device)
